using System.IO;
using System.Text.Json;
using UnscRelay.Core;
namespace UnscRelay.App;
public partial class MainWindow
{
 sealed record BridgeOrigin(string ProfileId,string Host,int Port,string Username,string? NativeSnapshot,string Path);
 sealed record BridgePlan(long Generation,SshSession Source,SshSession Target,RemoteBridgePreview Preview,DateTimeOffset Expires);
 readonly Dictionary<Guid,BridgePlan> bridgePlans=[];
 Func<string,bool>? bridgeTestConsent;
 bool ConfirmBridgeTransfer(string review)=>filesSmokeTest&&bridgeTestConsent!=null?bridgeTestConsent(review):Confirm(review);
 static BridgeOrigin BridgeBinding(SshSession session,string path)=>new(session.Profile.Id,session.Profile.Protocol=="native"?session.Profile.Native.Target:session.Profile.Host,session.Profile.Protocol=="native"?(session.Profile.Native.Port>0?session.Profile.Native.Port:22):session.Profile.Port,session.Profile.Username,session.Profile.Protocol=="native"?NativeRecovery.Snapshot(session.Profile):null,path);
 SshSession BridgeSource(FileJob job){var origin=job.Origin??throw new IOException("Sorgente della copia non disponibile.");if(string.IsNullOrWhiteSpace(origin.ProfileId)||origin.Host is not{Length:>0 and <=4096}||origin.Port is <1 or >65535||origin.Path is not{Length:>0 and <=4096}||origin.Path.Any(char.IsControl)||!origin.Path.StartsWith('/'))throw new IOException("Sorgente della coda non valida.");var binding=new FileJob{ProfileId=origin.ProfileId,Host=origin.Host,Port=origin.Port,Username=origin.Username,NativeSnapshot=origin.NativeSnapshot};foreach(var candidate in sessions.Values.Where(session=>session.Profile.Id==origin.ProfileId&&session.FilesAvailable)){try{CheckJobEndpoint(binding,candidate);return candidate;}catch(IOException){}}throw new IOException("Riapri la connessione sorgente originale prima di riprendere la copia.");}
 async Task<object?> BridgeAction(string action,JsonElement p){
  var generation=authenticationGeneration;RequireOperationSession(generation);if(action=="fileBridgeTargets")return sessions.Values.Where(session=>session.FilesAvailable).Select(session=>new{session.Id,session.Profile.Name,directory=session.HomeDirectory}).ToArray();
  foreach(var old in bridgePlans.Where(pair=>pair.Value.Generation!=generation||pair.Value.Expires<=DateTimeOffset.UtcNow).Select(pair=>pair.Key).ToArray())bridgePlans.Remove(old);
  if(action=="fileBridgeCancel"){var id=p.GetProperty("id").GetGuid();return bridgePlans.TryGetValue(id,out var value)&&value.Generation==generation&&bridgePlans.Remove(id);}
  if(action=="fileBridgePlan"){
   if(bridgePlans.Count>=20)throw new IOException("Chiudi le anteprime precedenti e riprova tra cinque minuti.");var source=Session(p);if(!sessions.TryGetValue(S(p,"targetSessionId"),out var target)||!source.FilesAvailable||!target.FilesAvailable)throw new IOException("Apri entrambe le sessioni SFTP.");using var stop=CancellationTokenSource.CreateLinkedTokenSource(accountOperationStop.Token);stop.CancelAfter(TimeSpan.FromSeconds(20));var preview=await source.BridgePreflightAsync(target,S(p,"sourcePath"),S(p,"targetPath"),stop.Token);RequireOperationSession(generation);var id=Guid.NewGuid();bridgePlans[id]=new(generation,source,target,preview,DateTimeOffset.UtcNow.AddMinutes(5));return new{id,preview};
  }
  var planId=p.GetProperty("id").GetGuid();if(!bridgePlans.TryGetValue(planId,out var plan)||plan.Generation!=generation)throw new IOException("Anteprima scaduta: ripeti la verifica.");if(!sessions.TryGetValue(plan.Source.Id,out var currentSource)||!ReferenceEquals(currentSource,plan.Source)||!sessions.TryGetValue(plan.Target.Id,out var currentTarget)||!ReferenceEquals(currentTarget,plan.Target))throw new IOException("Le connessioni sono cambiate. Ripeti l’anteprima.");if(fileJobs.Count>=5000||fileJobs.Values.Any(job=>job.SessionId==plan.Target.Id&&job.Request.Remote==plan.Preview.Destination&&job.Status is not("Completato" or "Saltato")))throw new IOException("Destinazione già in coda o coda piena.");
  using var check=CancellationTokenSource.CreateLinkedTokenSource(accountOperationStop.Token);check.CancelAfter(TimeSpan.FromSeconds(20));var fresh=await plan.Source.BridgePreflightAsync(plan.Target,plan.Preview.Source,plan.Preview.Destination,check.Token);RequireOperationSession(generation);if(fresh.Size!=plan.Preview.Size||fresh.SourceModified!=plan.Preview.SourceModified||fresh.DestinationExists!=plan.Preview.DestinationExists||fresh.DestinationSize!=plan.Preview.DestinationSize||fresh.DestinationModified!=plan.Preview.DestinationModified)throw new IOException("Sorgente o destinazione cambiate: ripeti l’anteprima.");var replace=p.TryGetProperty("replace",out var replacement)&&replacement.GetBoolean();if(fresh.DestinationExists&&!replace)throw new IOException("La destinazione esiste: conferma esplicitamente la sostituzione.");if(fresh.AvailableBytes is{} available&&available<fresh.Size)throw new IOException("Spazio insufficiente sul server di destinazione.");
  if(!ConfirmBridgeTransfer(NativeText("Confermi la copia tra questi server?")+"\n\n"+plan.Source.Profile.Name+"\n"+fresh.Source+"\n→\n"+plan.Target.Profile.Name+"\n"+fresh.Destination+"\n\n"+NativeText("Copia un file tra due sessioni SFTP già aperte. I dati passano nella memoria del PC, senza una copia completa sul disco locale. Il server di destinazione conserva un file parziale fino alla verifica. La sorgente non viene eliminata.")))throw new OperationCanceledException();var production=ConfirmProductionOperation(plan.Target.Profile,"Copia tra server tramite questo PC",resource:fresh.Destination);RequireOperationSession(generation);var origin=BridgeBinding(plan.Source,fresh.Source);var destination=BridgeBinding(plan.Target,fresh.Destination);var jobId=Guid.NewGuid().ToString("N");var job=new FileJob{Id=jobId,SessionId=plan.Target.Id,ProfileId=destination.ProfileId,Host=destination.Host,Port=destination.Port,Username=destination.Username,NativeSnapshot=destination.NativeSnapshot,Origin=origin,ProductionApproved=production,Request=new(jobId,"relay-bridge:"+fresh.Source,fresh.Destination,true,replace?"replace":"new")};fileJobs.Add(job.Id,job);bridgePlans.Remove(planId);job.Running=RunJob(job,false);return QueueSnapshot();
 }
}
